import{_ as n,C as a,c as r,o as s,aj as l,G as t,w as d}from"./chunks/framework.Bfdr4H5E.js";const u="/sk/images/Trading-Log.webp",w=JSON.parse('{"title":"Additional Documentation","description":"","frontmatter":{"outline":"deep","prev":{"text":"Longer-Term Reviews","link":"/trading-with-pav/longer-term-reviews"},"next":{"text":"FACT Most Traders Will Fail to Achieve Consistent Profitability","link":"/trading-with-pav/fact-most-traders-will-fail-to-achieve-consistent-profitability"}},"headers":[],"relativePath":"trading-with-pav/additional-documentation.md","filePath":"trading-with-pav/additional-documentation.md"}'),h={name:"trading-with-pav/additional-documentation.md"};function c(p,e,f,m,g,y){const o=a("GraphComment"),i=a("ClientOnly");return s(),r("div",null,[e[0]||(e[0]=l('<h1 id="additional-documentation" tabindex="-1">Additional Documentation <a class="header-anchor" href="#additional-documentation" aria-label="Permalink to &quot;Additional Documentation&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#additional-documentation-1">Additional Documentation</a><ul><li><a href="#trading-journal-spreadsheet">Trading Journal Spreadsheet</a></li><li><a href="#trading-log">Trading Log</a></li><li><a href="#motivation-journal">Motivation Journal</a></li><li><a href="#lessons-learnt-journal">Lessons Learnt Journal</a></li><li><a href="#market-structure-journal">Market Structure Journal</a></li><li><a href="#trades-journal">Trades Journal</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="additional-documentation-1" tabindex="-1">Additional Documentation <a class="header-anchor" href="#additional-documentation-1" aria-label="Permalink to &quot;Additional Documentation&quot;">​</a></h2><p>In addition to our Trading Plan and our Procedures Manual, we make use of the following documents:</p><ul><li>Trading Journal Spreadsheet</li><li>Trading Log</li><li>Motivation Journal</li><li>Lessons Learnt Journal</li><li>Market Structure Journal</li><li>Trades Journal</li></ul><p>For all of these documents, make use of online storage if you prefer. However I find a paper-based system is best for all except the Trading Journal Spreadsheet. This is simply due to the fact that you’re more likely to refer to an easily accessible paper-based journal. Your call though!</p><h3 id="trading-journal-spreadsheet" tabindex="-1">Trading Journal Spreadsheet <a class="header-anchor" href="#trading-journal-spreadsheet" aria-label="Permalink to &quot;Trading Journal Spreadsheet&quot;">​</a></h3><p>This is a spreadsheet, used for recording and analyzing your trade statistics. It’s an essential tool for analyzing your win percentage and win/loss size ratio, for all the subsets of trade data. We spoke about the need for this spreadsheet in <a href="/sk/trading-with-pav/goals-targets/">article 73</a> in stats section.</p><p>The Trading Journal Spreadsheet which I currently use will be listed on my YSTC Resources Page, under the heading of Business Management:<br><a href="/sk/resources.html">Resources</a>.</p><h3 id="trading-log" tabindex="-1">Trading Log <a class="header-anchor" href="#trading-log" aria-label="Permalink to &quot;Trading Log&quot;">​</a></h3><p>The trading log is the primary document I use on a daily basis for recording anything and everything which occurs pre-session, during session and post-session.</p><p>I’ve trialed different logs in the past – one for trading data; one for psych notes. I’ve found it’s too hard to switch back and forth during the session. I now put everything in one.</p><p>I use an A4 size lecture pad, which can then be inserted in a ring binder for archiving, once full.</p><p><img src="'+u+'" alt="Trading-Log"></p><p>Trading Log</p><p>Data is entered under headings of Date, Prep, Notes, Trading Session Review, Performance Review and Next Section, as guided by the procedures manual.</p><p>In the margin alongside any Notes or Review text, I place a short code to allow me to quickly identify the nature of this text. Codes are as follows:</p><ul><li>AN = analysis</li><li>TR = trading</li><li>MK = market structure observation</li><li>LL = lesson learnt</li><li>PERS = personal / psych observation</li><li>? = anything else of potential or unknown significance which needs to be considered during the post-session review</li></ul><p>This coding of the trading log entries is not essential, but it makes it easier to find all data related to one topic, amongst the whole session’s log entries. For example, if I wanted to review any personal performance or psych observations, I just look for the PERS codes.</p><p>The prep section contains any pre-session information, such as date, market, session times, position sizes, key news events etc.</p><p>The notes section then contains anything I want to record during the session – key analysis observations such as slowing momentum or expected setups; trade entry parameters such as the entry, stop and target prices; psych observations such as your feelings the time of entry. And naturally, anything I feel should be reviewed post-session and anything which I feel is suitable for inclusion in our market structure, lessons learnt journals.</p><p>One final point… I find it beneficial for analysis and trade notes to preface each note with the current time, in case you wish to cross reference the notes with a chart.</p><h3 id="motivation-journal" tabindex="-1">Motivation Journal <a class="header-anchor" href="#motivation-journal" aria-label="Permalink to &quot;Motivation Journal&quot;">​</a></h3><p>The motivation journal was discussed in detail in <a href="/sk/trading-with-pav/mastery-of-trading-psychology/#motivational-journal">article 75</a>.</p><h3 id="lessons-learnt-journal" tabindex="-1">Lessons Learnt Journal <a class="header-anchor" href="#lessons-learnt-journal" aria-label="Permalink to &quot;Lessons Learnt Journal&quot;">​</a></h3><p>The lessons learnt journal is a loose-leaf folder containing the following sections:</p><ul><li>Market Structure</li><li>Price Action</li><li>Setups</li><li>Trade Entry</li><li>Trade Management / Exit</li><li>Psychology</li><li>Business Management</li><li>Learning to Trade</li><li>Miscellaneous</li></ul><p>You may prefer to use a spreadsheet or some other form of online document. I have tried that for quite a while; however I found that I was not referring to it very often for study purposes. A paper-based system is preferable simply due to it being easily accessible.</p><p>Within each section I simply record ANY significant observation or lesson from the categories. This primarily occurs during the post-session review, but can also occur at any other time such as upon discovering a key lesson while reading a trading book.</p><p>Interestingly, you’ll find that as you develop in your knowledge and skills, you’ll review your lessons learnt journal and discover items that no longer have relevance to the way you trade or to your beliefs about the markets. When that occurs I simply cross them out. No problems!</p><h3 id="market-structure-journal" tabindex="-1">Market Structure Journal <a class="header-anchor" href="#market-structure-journal" aria-label="Permalink to &quot;Market Structure Journal&quot;">​</a></h3><p>I previously wrote about the market structure journal in a free eBook release, entitled, “The Greatest Trading Book – Ever!” There was a copy available on the download page for this eBooks series.</p><p>You can also find it at the YSTC eBooks’ page: <a href="/sk/ebooks.html">https://www.ystc.in/ebooks</a></p><p>The market structure journal is an incredibly valuable tool for building your intuitive ability to identify the nature of the current market and identify structural changes in real-time.</p><p>The best format in my opinion is a folder, allowing loose sheets to be inserted after each trading session.</p><p>Print charts for the trading timeframe, and use a pen to document any key structural features on the printed price action.</p><p>You may prefer to just file each session sequentially, or you may wish to file them in sections, according to market environment:</p><ul><li>Trending / Volatile</li><li>Trending / Non-volatile</li><li>Ranging / Volatile</li><li>Ranging / Non-volatile</li><li>Combination</li></ul><h3 id="trades-journal" tabindex="-1">Trades Journal <a class="header-anchor" href="#trades-journal" aria-label="Permalink to &quot;Trades Journal&quot;">​</a></h3><p>This is a loose-leaf folder containing printouts of trades.</p><p>I did try keeping them electronically for quite a while (saved as a .jpg), but found I was never referring to them. Paper takes up a lot of room, but at least they are easily accessible for review and ongoing learning purposes.</p><p>Importantly, there is no need to keep printouts of every trade (unless you wish to). I prefer to only keep those which I feel offer some learning potential – those particularly well managed, and those which were poorly managed.</p><p>I prefer to keep this as a separate journal. Sometimes I’m just in the mood to look at some trades!</p><p>You may wish to keep them filed sequentially by date, or separate them into sections based upon the setup. I’ve found I prefer the first. Trial both and find what works best for you.</p><p>If you prefer to cut down on the number of separate journals, you have some other options:</p><ul><li>If your trading log is a loose-leaf folder, insert your trade printouts following each session’s trade log entries.</li><li>If your lessons learnt folder is a loose-leaf folder, insert your trade printouts in a Trades section.</li></ul><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',47)),t(i,null,{default:d(()=>[t(o)]),_:1})])}const v=n(h,[["render",c]]);export{w as __pageData,v as default};
